module protocol::emode_admin;

use std::type_name::TypeName;
use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::limiter::NewLimiter;
use protocol::emode::{new_emode_params, NewEMode};

const EMODE_CREATED: u8 = 0;
const EMODE_UPDATED: u8 = 1;

const BPS_DENOMINATOR: u64 = 10000;

public struct NewEModeGroupEvent has copy, drop {
    market: TypeName,
    emode_group_id: u8,
    oracle_base_token: u8,
    time: u64,
    operator: address,
}

public struct EModeUpdated<T> has copy, drop {
    who: address,
    what: u8,
    market: TypeName,
    asset: TypeName,
    new: T
}

public fun create_limiter(
    _: &AdminCap,
    self: &ProtocolApp,
    outflow_limit: u64,
    outflow_cycle_duration: u32,
    outflow_segment_duration: u32,
): protocol::limiter::NewLimiter {
    self.ensure_version_matches();

    protocol::limiter::create_new_limiter_change(outflow_limit, outflow_cycle_duration, outflow_segment_duration)
}

public fun onboard_new_emode_group<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    oracle_base_token: u8,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let id = market.emode_registry_mut().new_emode_group(oracle_base_token, ctx);
    let now = clock.timestamp_ms() / 1000;

    emit(NewEModeGroupEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        emode_group_id: id,
        oracle_base_token,
        time: now,
        operator: ctx.sender(),
    });
}

public fun create_emode_params(
    cap: &AdminCap,
    self: &ProtocolApp,

    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    assert!(collateral_factor_bps < liquidation_factor_bps, error::invalid_params_error());
    assert!(liquidation_factor_bps - collateral_factor_bps < liquidation_incentive_bps, error::invalid_params_error());

    self.ensure_version_matches();

    // liquidation factor * (1 + liquidation incentive) < 1
    assert!(
        liquidation_factor_bps * (BPS_DENOMINATOR + liquidation_incentive_bps) / BPS_DENOMINATOR < BPS_DENOMINATOR,
        error::invalid_params_error()
    );

    create_emode_params_inner(
        cap,
        collateral_factor_bps,

